// Convex signs "<timestamp>.<body>" with N8N_WEBHOOK_SECRET (HMAC-SHA256). The body was produced
// by JSON.stringify, so re-serialising the parsed body gives back the exact signed bytes.
const crypto = require('crypto');
const secret = $env.LENDLOOP_N8N_WEBHOOK_SECRET;
const { headers, body } = $input.first().json;
const ts = headers['x-lendloop-timestamp'] || '';
const sig = headers['x-lendloop-signature'] || '';
const fresh = /^\d+$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const expected = 'sha256=' + crypto.createHmac('sha256', secret || '').update(`${ts}.${JSON.stringify(body)}`).digest('hex');
const valid = Boolean(secret) && fresh && sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
return [{ json: { valid, payload: valid ? body : null } }];

// Uses only what the message needs: first name, email, tool name, dates, status.
// Duplicate deliveries (Convex retries after a timeout) are skipped by idempotency key.
// To send real email, replace this node with a Send Email node using an SMTP credential.
const p = $input.first().json.payload;
const seen = $getWorkflowStaticData('global');
seen.keys = seen.keys || {};
if (seen.keys[p.idempotencyKey]) return [{ json: { ok: true, duplicate: true } }];

const when = `${p.startDate} – ${p.endDate}`;
const text = {
  'loan.pending':   `Hi ${p.recipient.firstName}, a neighbour asked to borrow your ${p.tool} for ${when}. Open LendLoop to approve or decline.`,
  'loan.cancelled': `Hi ${p.recipient.firstName}, the request for your ${p.tool} (${when}) was withdrawn.`,
  'loan.approved':  `Hi ${p.recipient.firstName}, good news: your request for the ${p.tool} (${when}) was approved.`,
  'loan.declined':  `Hi ${p.recipient.firstName}, your request for the ${p.tool} (${when}) was declined this time.`,
  'loan.returned':  `Hi ${p.recipient.firstName}, thanks for returning the ${p.tool}.`,
}[p.event];
if (!text) throw new Error(`Unknown event ${p.event}`);

console.log('[LendLoop mock email]', JSON.stringify({ to: p.recipient.email, subject: 'LendLoop update', text }));

// Keep the last 500 keys so the store can't grow without bound.
seen.keys[p.idempotencyKey] = Date.now();
const keys = Object.keys(seen.keys);
if (keys.length > 500) for (const k of keys.sort((a, b) => seen.keys[a] - seen.keys[b]).slice(0, keys.length - 500)) delete seen.keys[k];
return [{ json: { ok: true, duplicate: false } }];
